[Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)
$ErrorActionPreference = 'Stop'
$Utf8 = [System.Text.UTF8Encoding]::new($false)
$Root = (Get-Location).Path
$BlogDir = Join-Path $Root 'blog'
$ArticlesDir = Join-Path $BlogDir 'articles'
$ImagesDir = Join-Path $Root 'assets\images'
$Site = 'https://storesads.shop'
$WhatsApp = '201110760081'
$Banner = '/assets/images/site-banner-arabsad.jpg'
$Logo = '/assets/images/logo-arabsad.jpg'

if (!(Test-Path (Join-Path $ImagesDir 'site-banner-arabsad.jpg'))) { throw 'Missing assets/images/site-banner-arabsad.jpg' }
if (!(Test-Path (Join-Path $ImagesDir 'logo-arabsad.jpg'))) { throw 'Missing assets/images/logo-arabsad.jpg' }
New-Item -ItemType Directory -Path $ArticlesDir -Force | Out-Null

function Write-Utf8File([string]$Path, [string]$Content) {
  [System.IO.File]::WriteAllText($Path, $Content, $Utf8)
}
function Esc([string]$Text) { [System.Uri]::EscapeDataString($Text) }

$Articles = @(
  @{k='شركات تسويق سوشيال ميديا';s='sharikat-taswiq-social-media';c='سوشيال ميديا';a='اختيار شركة سوشيال ميديا يجب أن يبدأ بمراجعة خبرتها في نشاطك وقدرتها على تقديم تقارير مبيعات وتحويلات، لا تقارير إعجابات فقط.';b='الخطة الناجحة تربط المحتوى العضوي بالحملات المدفوعة وإعادة الاستهداف، بحيث يرى العميل رسالة واحدة في كل مرحلة من رحلة الشراء.';d='اطلب مؤشرات أداء واضحة مثل تكلفة اكتساب العميل ومعدل التحويل وعدد الطلبات من كل منصة قبل توسيع الميزانية.'},
  @{k='شركات اعلان وتسويق';s='sharikat-elan-w-taswiq';c='استراتيجية';a='شركات الإعلان والتسويق المتكاملة تبدأ بفهم المنتج والجمهور والمنافسين قبل إطلاق أي حملة مدفوعة.';b='الحملة المتكاملة تجمع صفحة هبوط واضحة ومحتوى يشرح القيمة وإعلانات تصل للشريحة الأكثر احتمالاً للشراء.';d='افصل بين رسوم الإدارة وميزانية الإعلانات وحدد مع الشريك التسويقي ما الذي سيقاس في التقرير الشهري.'},
  @{k='اعلان ممول في سناب شات';s='elan-mamol-snapchat';c='سناب شات';a='إعلان سناب شات الممول يحتاج فيديو عمودي سريع يوضح الفائدة خلال الثواني الأولى ويتوافق مع سلوك المستخدم على المنصة.';b='تركيب Snap Pixel قبل التشغيل يساعد على تتبع الزيارات والطلبات وتحسين الاستهداف بناءً على بيانات فعلية.';d='ابدأ بميزانية اختبار صغيرة، واختبر أكثر من نسخة إعلانية قبل زيادة الإنفاق على الإعلان الأفضل.'},
  @{k='الاعلان الممول على فيس بوك';s='elan-mamol-facebook';c='فيسبوك';a='الإعلان الممول على فيس بوك ينجح عند تحديد هدف واضح للحملة: مبيعات أو عملاء محتملون أو وعي بالعلامة.';b='قسّم الجمهور إلى مجموعات إعلانية صغيرة وقارن تكلفة التحويل بين الشرائح بدلاً من وضع كل الاهتمامات في مجموعة واحدة.';d='إعادة استهداف زوار الموقع والمتفاعلين مع المحتوى غالباً تخفض تكلفة العميل لأنهم عرفوا علامتك مسبقاً.'},
  @{k='شركة تسويق منتجات الغير';s='sharikat-taswiq-montajat-alghayr';c='تجارة إلكترونية';a='شركة تسويق منتجات الغير تساعد التاجر على تسويق منتجات لا يخزنها بنفسه، بينما يتولى المورد التنفيذ والشحن.';b='لأن المنتج قد يكون متاحاً عند أكثر من متجر، يصبح التميز في العرض والإعلان وخدمة العميل هو العامل الحاسم.';d='اختبر المنتج بإعلان منخفض الميزانية وتأكد من سرعة المورد وجودة الشحن قبل توسيع الاستثمار.'},
  @{k='شركة مشاهير للتسويق';s='sharikat-mashaheer-taswiq';c='مؤثرون';a='التسويق بالمشاهير ينجح عندما يتوافق جمهور المؤثر مع المنتج، وليس لمجرد أن لديه عدداً كبيراً من المتابعين.';b='المؤثرون المتوسطون قد يقدمون تفاعلاً وثقة أعلى بتكلفة مناسبة للمتاجر الصغيرة والمتوسطة.';d='استخدم كود خصم أو رابط تتبع لكل مؤثر حتى تقيس المبيعات الحقيقية الناتجة عن التعاون.'},
  @{k='مكتب تسويق منتجات';s='maktab-taswiq-montajat';c='منتجات';a='مكتب تسويق المنتجات المحترف يبدأ من صور المنتج ووصفه ويحول خصائصه إلى فوائد واضحة للعميل.';b='بعد تجهيز المحتوى، يتم اختبار الإعلان على القنوات المناسبة ثم توجيه الميزانية تدريجياً للأداء الأفضل.';d='اسأل عن تصوير المنتجات وكتابة الوصف وإدارة الحملة والتحليل ضمن عرض خدمة واحد واضح.'},
  @{k='شركات تسويق عالمية';s='sharikat-taswiq-alamiya';c='مقارنة';a='شركات تسويق عالمية قد تناسب النشاط الذي يخاطب أسواقاً متعددة ولغات مختلفة، لكنها ليست الأفضل تلقائياً لكل مشروع.';b='الشركة المحلية تفهم اللهجة والعادات الشرائية في السوق العربي وتستطيع إنتاج رسائل أقرب للجمهور.';d='اختر حسب جمهورك وجودة التقارير وسرعة التواصل والخبرة القطاعية، لا حسب حجم الاسم فقط.'},
  @{k='افضل موقع تسويق الكتروني';s='afdal-mawqe-taswiq-elektroni';c='تسويق إلكتروني';a='لا يوجد موقع تسويق إلكتروني واحد يناسب جميع الأنشطة، لأن الاختيار يعتمد على هدفك وميزانيتك والجمهور.';b='ابحث عن إمكانية تتبع الزيارات والتحويلات وتكلفة اكتساب العميل بدلاً من الاعتماد على وعود عامة.';d='المنصات الذاتية تناسب من يملك وقتاً وخبرة، بينما الشريك المتخصص يناسب من يريد إدارة متكاملة.'},
  @{k='اعلان سناب ممول';s='elan-snap-mamol';c='سناب شات';a='إعلان سناب ممول قد يكون فيديو قصيراً أو عرض منتجات أو إعلان قصص، ويعتمد الاختيار على هدف الحملة.';b='إعلانات Collection تناسب المتاجر التي تعرض عدة منتجات، بينما Snap Ads مناسبة للرسائل السريعة.';d='راقب معدل إكمال المشاهدة والنقرات والتحويلات لتحديد النسخة التي تستحق زيادة الميزانية.'},
  @{k='تسويق موقع الكتروني';s='taswiq-mawqe-elektroni';c='مواقع';a='تسويق موقع إلكتروني يبدأ بتحديد الصفحات التي تحول الزائر إلى عميل وتحسين الرسالة داخلها.';b='اجمع بين تحسين محركات البحث والإعلانات الممولة والمحتوى لتصل إلى جمهور يبحث فعلياً عن خدمتك.';d='تأكد من سرعة الموقع ووضوح دعوة الإجراء وتتبع التحويلات قبل زيادة ميزانية الإعلانات.'},
  @{k='تسويق متجر';s='taswiq-matjar';c='متاجر';a='تسويق متجر يحتاج عرضاً واضحاً ومنتجات موثوقة ومسار شراء بسيطاً على الهاتف قبل أي حملة إعلانية.';b='اختبر منتجاتك وعروضك مع شرائح مختلفة، ثم استخدم إعادة الاستهداف لمن زار المتجر ولم يكمل الطلب.';d='راقب تكلفة الطلب ومتوسط قيمة السلة ونسبة إتمام الشراء لتحديد القنوات الأكثر ربحية.'},
  @{k='مكاتب تسويق الكتروني';s='makatib-taswiq-elektroni';c='خدمات';a='مكاتب التسويق الإلكتروني تختلف في تخصصاتها، لذلك اختر مكتباً يملك خبرة في نوع نشاطك وليس في عدد الخدمات فقط.';b='الخدمة الجيدة تشمل دراسة الجمهور والمحتوى والإعلان والتحليل، مع تواصل منتظم وتقارير قابلة للفهم.';d='اطلب خطة أول 30 يوماً قبل التعاقد لتعرف ما الذي سيُنفذ وكيف ستقاس النتائج.'},
  @{k='حملة تسويق الكتروني';s='hamlat-taswiq-elektroni';c='حملات';a='حملة تسويق إلكتروني ناجحة تبدأ بهدف واحد يمكن قياسه، مثل طلبات شراء أو تسجيل بيانات أو زيارات مؤهلة.';b='اختيار القناة يعتمد على مكان وجود جمهورك: البحث للطلب الجاهز، والسوشيال ميديا للاكتشاف والتفاعل.';d='اختبر الرسائل والعروض والجمهور بشكل منظم، ولا تغير كل عناصر الحملة في الوقت نفسه.'},
  @{k='انشاء اعلان ممول على الانستقرام';s='insha-elan-mamol-instagram';c='إنستغرام';a='إنشاء إعلان ممول على الانستقرام يحتاج هدفاً واضحاً ومادة بصرية مناسبة للريلز والقصص والمنشورات.';b='ابدأ بإعداد Meta Pixel وربط المتجر أو صفحة الهبوط لتقيس الطلبات وليس المشاهدات فقط.';d='استخدم صوراً أو فيديوهات عمودية مع نص قصير وفائدة واضحة ودعوة مباشرة للشراء أو التواصل.'},
  @{k='تسويق لموقع الكتروني';s='taswiq-limawqe-elektroni';c='مواقع';a='تسويق لموقع إلكتروني يعني جذب زوار مناسبين ثم تحويلهم عبر تجربة مستخدم ورسالة وعرض واضح.';b='الزيارات غير المؤهلة لا تعني مبيعات، لذلك ركز على كلمات بحث أو اهتمامات مرتبطة بنية العميل.';d='ضع قياساً للتحويلات في الموقع حتى تعرف أي قناة تسويقية تستحق الميزانية.'},
  @{k='شركة تسويق إعلانات';s='sharikat-taswiq-elanat';c='إعلانات';a='شركة تسويق إعلانات جيدة تدير الميزانية وفق بيانات وليس وفق التخمين أو عدد النقرات فقط.';b='العمل الاحترافي يشمل كتابة النصوص وتصميم الإبداع الإعلاني واختيار الجمهور وتحسين الحملة بانتظام.';d='راجع التقارير وتأكد أن التكلفة مرتبطة بهدف تجاري مثل طلب أو رسالة أو تسجيل.'},
  @{k='اعلان يوتيوب ممول';s='elan-youtube-mamol';c='يوتيوب';a='إعلان يوتيوب ممول مناسب لبناء الوعي وشرح المنتج أو الخدمة بالفيديو أمام جمهور محدد.';b='الخطاف في أول خمس ثوانٍ مهم لأن المشاهد يقرر سريعاً هل سيكمل الفيديو أو يتخطاه.';d='استخدم جماهير مخصصة وإعادة استهداف، واربط الفيديو بصفحة هبوط بسيطة وسريعة.'},
  @{k='فريق تسويق الكتروني';s='fareeq-taswiq-elektroni';c='فرق';a='فريق تسويق إلكتروني متكامل يجمع المحتوى والتصميم والإعلانات والتحليل بدلاً من العمل المنفصل بين مهام غير مترابطة.';b='وضوح الأدوار يساعد على تسليم أسرع: من يكتب، من يصمم، من يراقب الأرقام، ومن يتواصل مع العميل.';d='ابحث عن فريق يقدم تقارير مختصرة وواضحة ويقترح تحسينات مبنية على نتائج حقيقية.'},
  @{k='متجر تسويق الكتروني';s='matjar-taswiq-elektroni';c='متاجر';a='متجر تسويق إلكتروني يحتاج هوية واضحة وصفحات منتجات مقنعة وطرق دفع وشحن مفهومة للعميل.';b='بعد بناء المتجر، ركز على جلب الزيارات المؤهلة من الإعلانات والبحث والمحتوى بدل الاعتماد على مصدر واحد.';d='حلل المنتجات الأكثر طلباً والعروض التي ترفع متوسط السلة لتطوير الحملة باستمرار.'},
  @{k='شركات تسويق مصرية';s='sharikat-taswiq-masria';c='مصر';a='شركات تسويق مصرية تقدم خيارات متنوعة للأنشطة المحلية والخليجية، لكن الخبرة القطاعية أهم من السعر وحده.';b='اختر شركة تفهم جمهورك المستهدف ولديها نظام واضح للتقارير والتواصل وإدارة الحملات.';d='اطلب أمثلة على طريقة العمل ومؤشرات القياس بدلاً من الاعتماد على وعود نتائج غير مضمونة.'},
  @{k='اعلان ممول سناب';s='elan-mamol-snap';c='سناب شات';a='إعلان ممول سناب يحتاج محتوى متناسباً مع شاشة الهاتف وفكرة واحدة سهلة الفهم.';b='حدد إن كان الهدف زيارة متجر أو رسالة واتساب أو وعي بالعلامة، ثم اختر نوع الإعلان المناسب.';d='اختبر الجمهور والمادة الإعلانية معاً لكن غيّر عنصراً واحداً في كل تجربة لتعرف سبب التحسن.'},
  @{k='شركات الاعلانات الممولة';s='sharikat-elanat-mamola';c='إعلانات';a='شركات الإعلانات الممولة تساعد على إدارة الميزانيات عبر جوجل وميتا وسناب وتيك توك وفق هدف تجاري محدد.';b='لا تقارن الشركات بالسعر فقط؛ قارن بينها بطريقة التتبع والتقارير وخبرة المجال وسرعة التحسين.';d='اطلب ملكية حسابات الإعلانات والبيكسلات حتى تبقى بيانات نشاطك تحت سيطرتك.'},
  @{k='اعلان انستقرام ممول';s='elan-instagram-mamol';c='إنستغرام';a='إعلان انستقرام ممول فعال يبدأ بفكرة بصرية واضحة تشرح المنتج أو العرض خلال ثوانٍ.';b='استخدم الريلز والقصص بحسب نوع المحتوى، واختبر زر الإجراء المناسب مثل تسوق الآن أو إرسال رسالة.';d='تابع تكلفة الرسالة أو الشراء، وليس عدد الإعجابات فقط، لتحسين الإنفاق.'},
  @{k='ادارة التسويق الالكتروني';s='idarat-taswiq-elektroni';c='إدارة';a='إدارة التسويق الإلكتروني هي تنظيم القنوات والميزانيات والمحتوى والتقارير ضمن خطة واحدة قابلة للقياس.';b='المدير الناجح يحدد الأولويات ويمنع تشتت الجهد بين منصات لا تخدم هدف النشاط.';d='أنشئ لوحة متابعة أسبوعية تشمل الزيارات والتحويلات والتكلفة والعائد لتطوير القرارات.'},
  @{k='اعلان ممول تيك توك';s='elan-mamol-tiktok';c='تيك توك';a='إعلان ممول تيك توك يحتاج فيديو يبدو طبيعياً وسريعاً ويقدم قيمة أو عرضاً واضحاً من البداية.';b='استخدم هوك قوي في أول ثانية، وركز على منتج واحد أو مشكلة واحدة داخل الفيديو.';d='اختبر عدة فيديوهات قصيرة لأن أداء تيك توك يرتبط بقوة بالمحتوى الإبداعي.'},
  @{k='منصة تسويق الكتروني';s='mansat-taswiq-elektroni';c='منصات';a='منصة تسويق إلكتروني مفيدة عندما تقدم تتبعاً واضحاً للحملات والعملاء وتتكامل مع موقعك أو متجرك.';b='اختر المنصة حسب القنوات التي تحتاجها، وليس حسب عدد المزايا التي لن تستخدمها.';d='راجع سهولة التقارير والدعم والتكامل مع التحليلات قبل اعتماد أي منصة.'},
  @{k='افضل مسوق الكتروني';s='afdal-mosawiq-elektroni';c='خبرات';a='أفضل مسوق إلكتروني ليس من يعد بنتيجة مضمونة، بل من يوضح الفرضيات ويقيس النتائج ويعدل الخطة وفق البيانات.';b='المسوق المحترف يسأل عن المنتج والعميل والهامش والهدف قبل اقتراح منصة أو ميزانية.';d='اطلب خطة اختبار وتقارير ومعايير نجاح واضحة قبل بدء العمل.'},
  @{k='تسويق متجر الكتروني';s='taswiq-matjar-elektroni';c='متاجر';a='تسويق متجر إلكتروني يجمع تحسين المنتج والسعر والصفحة مع جذب زيارات مؤهلة من القنوات المناسبة.';b='صفحة المنتج يجب أن تعرض صوراً واضحة وفوائد وسعر وشحن ودعوة شراء بدون تشتيت.';d='ركز على تتبع الشراء والسلة المتروكة وإعادة الاستهداف لرفع كفاءة الإنفاق.'},
  @{k='شركة تسويق اعلانات';s='sharikat-taswiq-elanat';c='إعلانات';a='شركة تسويق إعلانات تدير التخطيط والتنفيذ والتحسين للحملات المدفوعة وفق أهداف نشاطك.';b='أفضل الحملات تربط الإعلان بصفحة هبوط مناسبة وبطريقة تواصل سهلة مثل واتساب أو نموذج واضح.';d='تحقق من وجود تقارير شفافة عن الميزانية والنقرات والتحويلات والعائد.'},
  @{k='شركات تسويق قنوات يوتيوب';s='sharikat-taswiq-qanawat-youtube';c='يوتيوب';a='شركات تسويق قنوات يوتيوب تساعد على تطوير المحتوى والعناوين والصور المصغرة والترويج للوصول إلى جمهور مناسب.';b='نمو القناة يحتاج توازناً بين محتوى قابل للبحث ومحتوى قابل للمشاركة، مع نشر منتظم.';d='راقب مدة المشاهدة والاحتفاظ بالمشاهد ونسبة النقر على الصورة المصغرة بدل التركيز على المشتركين فقط.'},
  @{k='مسوق الكتروني محترف';s='mosawiq-elektroni-mohtaref';c='خبرات';a='المسوق الإلكتروني المحترف يبدأ بتحليل العرض والسوق والجمهور ثم يختار القناة والرسالة والميزانية.';b='الاحتراف يظهر في توثيق الاختبارات وقراءة الأرقام والقدرة على إيقاف ما لا يعمل بسرعة.';d='ابحث عن مسوق يشرح المخاطر بوضوح ولا يقدم ضمانات غير واقعية بشأن المبيعات أو ترتيب جوجل.'},
  @{k='شركة تسويق رقمي';s='sharikat-taswiq-raqami';c='رقمي';a='شركة تسويق رقمي تقدم مزيجاً من الإعلانات والمحتوى والتحليلات لتحويل حضورك الرقمي إلى فرص نمو.';b='اختيار الخدمات يجب أن يرتبط بمرحلة نشاطك: بناء الوعي أو جمع العملاء المحتملين أو زيادة الطلبات.';d='حدد الهدف والميزانية والمدة ومؤشرات القياس قبل بدء أي تعاقد.'},
  @{k='تسويق لمتجر الكتروني';s='taswiq-limatjar-elektroni';c='متاجر';a='تسويق لمتجر إلكتروني يبدأ بفهم العميل والمنتجات ذات الهامش المناسب ثم بناء عروض قابلة للاختبار.';b='استخدم الإعلانات لجذب زوار مؤهلين، واهتم بسرعة المتجر وتجربة الهاتف وتفاصيل الشحن والدفع.';d='استفد من إعادة الاستهداف والبريد أو الرسائل لاستعادة العملاء الذين لم يكملوا الطلب.'},
  @{k='تسويق المتاجر الالكترونية';s='taswiq-matajer-elektronia';c='متاجر';a='تسويق المتاجر الإلكترونية يحتاج خطة تجمع اكتساب العميل وتحويله ثم الحفاظ عليه عبر تجربة شراء وخدمة جيدة.';b='اختيار المنصة الإعلانية يعتمد على المنتج والسوق: البحث للطلب الواضح والسوشيال للاكتشاف والعروض.';d='حلل الأرباح بعد تكلفة الإعلان والشحن والخصومات، وليس الإيرادات فقط.'},
  @{k='شركة حلول تسويقية';s='sharikat-holol-taswiqia';c='حلول';a='شركة حلول تسويقية تساعد النشاط على تشخيص المشكلة قبل اختيار الحل، فقد تكون المشكلة في العرض أو الصفحة أو الاستهداف.';b='الحلول المتكاملة تربط الهوية والمحتوى والإعلان والتحليلات بطريقة تخدم هدفاً واحداً.';d='اطلب خارطة طريق مرحلية حتى تفهم الأولويات قبل تخصيص ميزانية كبيرة.'},
  @{k='شركات تسويق الكترونى';s='sharikat-taswiq-electrony';c='خدمات';a='شركات تسويق إلكتروني تقدم خدمات مختلفة، لكن القيمة الحقيقية هي في الربط بين التنفيذ والنتائج القابلة للقياس.';b='اختر شركة تشرح بوضوح كيف ستصل للجمهور وكيف ستتابع التحويلات وكيف ستطور الحملة.';d='تجنب أي جهة تعدك بالمركز الأول أو بأرباح مضمونة دون دراسة السوق.'},
  @{k='عمل اعلانات ممولة';s='amal-elanat-mamola';c='إعلانات';a='عمل إعلانات ممولة يبدأ بتحديد الهدف والجمهور والرسالة والصفحة التي سيصل إليها العميل.';b='إعلان جيد لا يعوض صفحة هبوط ضعيفة، لذلك تأكد من وجود عرض واضح وطريقة تواصل أو شراء سهلة.';d='اختبر الإعلانات بميزانية صغيرة وسجل النتائج قبل اتخاذ قرار التوسع.'},
  @{k='شركة تسويق منتجات';s='sharikat-taswiq-montajat';c='منتجات';a='شركة تسويق منتجات تحول مواصفات المنتج إلى عرض مفهوم وتستخدم المحتوى والإعلان للوصول إلى العميل المناسب.';b='نجاح المنتج يعتمد على صور جيدة ووصف مقنع وسعر وشحن واضحين قبل زيادة ميزانية الإعلان.';d='ابدأ باختبار منظم لمنتج أو فئة واحدة، ثم وسّع ما يثبت قدرته على الربح.'},
  @{k='شركات اعلانات ممولة';s='sharikat-elanat-mamola-advanced';c='إعلانات';a='شركات إعلانات ممولة تساعد على توزيع الميزانية بين المنصات وفق هدف كل قناة وسلوك الجمهور.';b='المتابعة اليومية للأرقام مهمة لأن الأداء يتغير مع المنافسة والمواسم والجمهور والمادة الإعلانية.';d='احتفظ بملكية الحسابات واطلب تقارير تسهل فهم أين ذهبت الميزانية وما الذي تحقق منها.'}
)

function Write-Utf8([string]$Path,[string]$Content){[System.IO.File]::WriteAllText($Path,$Content,$Utf8)}
function New-Article([hashtable]$A){$url="$Site/blog/articles/$($A.s).html";$m=[uri]::EscapeDataString("أريد استشارة حول $($A.k)");@"
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>$($A.Title) | إعلانات العرب</title><meta name="description" content="$($A.a)"><meta name="robots" content="index,follow,max-image-preview:large"><link rel="canonical" href="$url"><meta property="og:type" content="article"><meta property="og:title" content="$($A.Title) | إعلانات العرب"><meta property="og:description" content="$($A.a)"><meta property="og:image" content="$Site$Banner"><meta property="og:url" content="$url"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="$Site$Banner"><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="../../assets/css/universal-header-footer.css"><style>:root{--bg:#0a0e27;--card:#1a1f3a;--gold:#ffb800;--muted:#a8b3c1;--green:#25d366}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#e8edf5;font-family:Cairo,sans-serif;line-height:1.9}main{max-width:850px;margin:96px auto 45px;padding:0 18px}h1,h2{color:var(--gold)}.lead{color:var(--muted)}.hero-image{width:100%;height:auto;border-radius:16px;margin:18px 0}.wa{display:inline-block;background:var(--green);color:#fff;text-decoration:none;font-weight:800;padding:9px 16px;border-radius:24px;margin:0 0 22px}.box{background:var(--card);border:1px solid rgba(255,184,0,.2);padding:22px;border-radius:14px;margin-top:26px}.box a{color:var(--gold)}</style><script type="application/ld+json">{"@context":"https://schema.org","@type":"BlogPosting","headline":"$($A.Title)","description":"$($A.a)","image":"$Site$Banner","datePublished":"2026-08-19","dateModified":"2026-08-19","author":{"@type":"Organization","name":"إعلانات العرب"},"publisher":{"@type":"Organization","name":"إعلانات العرب","logo":{"@type":"ImageObject","url":"$Site/assets/images/logo-arabsad.jpg"}},"mainEntityOfPage":{"@type":"WebPage","@id":"$url"}}</script></head><body><div data-include="../../shared-header.html"></div><main><h1>$($A.Title)</h1><p class="lead">$($A.k): دليل عملي للتخطيط والتنفيذ والقياس.</p><img class="hero-image" src="$Banner" alt="$($A.k) - إعلانات العرب" width="1600" height="675"><p>$($A.a)</p><a class="wa" href="https://wa.me/$WhatsApp?text=$m" target="_blank" rel="noopener noreferrer">💬 استفسر عبر واتساب</a><h2>خطوات عملية</h2><p>$($A.b)</p><a class="wa" href="https://wa.me/$WhatsApp?text=$m" target="_blank" rel="noopener noreferrer">💬 تواصل معنا عبر واتساب</a><h2>نصيحة مهمة</h2><p>$($A.d)</p><a class="wa" href="https://wa.me/$WhatsApp?text=$m" target="_blank" rel="noopener noreferrer">💬 اطلب استشارة الآن</a><div class="box"><h2>خدمات مرتبطة</h2><p><a href="/services/">خدمات التسويق والإعلانات</a> · <a href="/blog/">العودة إلى المدونة</a></p></div></main><div style="max-width:1200px;margin:0 auto 22px;padding:0 14px"><img src="$Banner" alt="إعلانات العرب - إعلانات احترافية على كل المنصات" loading="lazy" style="width:100%;height:auto;border-radius:16px"></div><div data-include="../../shared-footer.html"></div><script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[data-include]').forEach(async function(e){try{var f=e.getAttribute('data-include'),r=await fetch(f);if(!r.ok)r=await fetch('/'+f.replace(/^(\.\.\/)+/,''));if(r.ok)e.innerHTML=await r.text()}catch(x){console.log(x)}})})</script><script src="/assets/js/universal-header-footer.js" defer></script></body></html>
"@}

$cards=foreach($A in $Articles){"<article class=`"card`"><img src=`"$Banner`" alt=`"$($A.k) - إعلانات العرب`" loading=`"lazy`"><div><span>$($A.c)</span><h2>$($A.Title)</h2><p>$($A.a)</p><a href=`"articles/$($A.s).html`">اقرأ المقال</a></div></article>"};$cardsHtml=$cards -join "`n"
$blog=@"
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مدونة إعلانات العرب | التسويق الرقمي والإعلانات الممولة</title><meta name="description" content="مقالات ودلائل عملية عن التسويق الرقمي والإعلانات الممولة."><meta name="robots" content="index,follow"><link rel="canonical" href="$Site/blog/"><meta property="og:image" content="$Site$Banner"><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="../assets/css/universal-header-footer.css"><style>:root{--bg:#0a0e27;--card:#1a1f3a;--gold:#ffb800;--muted:#a8b3c1;--green:#25d366}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#e8edf5;font-family:Cairo,sans-serif;line-height:1.75}.page{max-width:1200px;margin:96px auto 50px;padding:0 18px}.hero{text-align:center}.hero h1{color:var(--gold);font-size:clamp(2rem,5vw,3rem)}.hero p{color:var(--muted)}.hero img{width:100%;max-width:1000px;border-radius:16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px;margin-top:30px}.card{background:var(--card);border:1px solid rgba(255,184,0,.18);border-radius:16px;overflow:hidden}.card>img{width:100%;height:145px;object-fit:cover}.card>div{padding:20px}.card span{color:var(--gold);font-size:.8rem;font-weight:800}.card h2{font-size:1.16rem}.card p{color:var(--muted);font-size:.92rem}.card a,.cta{display:inline-block;background:var(--gold);color:#111;text-decoration:none;font-weight:800;padding:9px 15px;border-radius:22px}.cta{background:var(--green);color:#fff}.notice{text-align:center;margin:30px 0;padding:24px;background:#1a1f3a;border-radius:16px}</style><script type="application/ld+json">{"@context":"https://schema.org","@type":"Blog","name":"مدونة إعلانات العرب","url":"$Site/blog/"}</script></head><body><div data-include="../shared-header.html"></div><main class="page"><section class="hero"><h1>مدونة إعلانات العرب</h1><p>أدلة عملية للتسويق الرقمي والإعلانات الممولة وتحسين مبيعات المتاجر والشركات.</p><img src="$Banner" alt="إعلانات العرب - إعلانات احترافية على كل المنصات"></section><section class="grid">$cardsHtml</section><section class="notice"><h2>هل تحتاج حملة مخصصة؟</h2><p>تواصل معنا للاستشارة حول نشاطك.</p><a class="cta" href="https://wa.me/$WhatsApp?text=$([uri]::EscapeDataString('أريد استشارة تسويقية'))" target="_blank">تواصل عبر واتساب</a></section></main><div data-include="../shared-footer.html"></div><script>document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[data-include]').forEach(async function(e){try{var f=e.getAttribute('data-include'),r=await fetch(f);if(!r.ok)r=await fetch('/'+f.replace(/^(\.\.\/)+/,''));if(r.ok)e.innerHTML=await r.text()}catch(x){console.log(x)}})})</script><script src="/assets/js/universal-header-footer.js" defer></script></body></html>
"@
$header="<header style=`"position:sticky;top:0;z-index:999;background:#0a0e27;border-bottom:1px solid rgba(255,184,0,.22);font-family:Cairo,sans-serif`" dir=`"rtl`"><div style=`"max-width:1200px;margin:auto;padding:10px 18px;display:flex;align-items:center;justify-content:space-between;gap:16px`"><a href=`"/`" style=`"display:flex;align-items:center;gap:10px;color:#fff;text-decoration:none;font-weight:900`"><img src=`"/assets/images/logo-arabsad.jpg`" alt=`"شعار إعلانات العرب`" width=`"44`" height=`"44`" style=`"border-radius:50%;object-fit:cover`"><span>إعلانات العرب</span></a><nav style=`"display:flex;gap:13px;align-items:center;flex-wrap:wrap`"><a href=`"/`" style=`"color:#e8edf5;text-decoration:none`">الرئيسية</a><a href=`"/services/`" style=`"color:#e8edf5;text-decoration:none`">الخدمات</a><a href=`"/blog/`" style=`"color:#e8edf5;text-decoration:none`">المدونة</a><a href=`"https://wa.me/$WhatsApp?text=$([uri]::EscapeDataString('أريد استشارة تسويقية'))`" target=`"_blank`" style=`"background:#25D366;color:#fff;padding:8px 14px;border-radius:22px;text-decoration:none`">واتساب</a></nav></div></header>"
$footer="<section style=`"background:#0a0e27;padding:20px 14px 0`" dir=`"rtl`"><img src=`"/assets/images/site-banner-arabsad.jpg`" alt=`"إعلانات العرب - إعلانات احترافية على كل المنصات`" loading=`"lazy`" style=`"display:block;width:100%;max-width:1200px;height:auto;margin:auto;border-radius:16px`"></section><footer style=`"background:#070b1e;color:#e8edf5;padding:28px 18px;text-align:center;font-family:Cairo,sans-serif`" dir=`"rtl`"><img src=`"/assets/images/logo-arabsad.jpg`" alt=`"شعار إعلانات العرب`" width=`"58`" height=`"58`" style=`"border-radius:50%;object-fit:cover`"><p style=`"font-weight:800`">إعلانات العرب</p><p style=`"color:#a8b3c1`">حلول التسويق الرقمي والإعلانات الممولة.</p><a href=`"https://wa.me/$WhatsApp?text=$([uri]::EscapeDataString('أريد استشارة تسويقية'))`" target=`"_blank`" style=`"color:#25D366;text-decoration:none;font-weight:800`">تواصل عبر واتساب</a></footer>"

Write-Utf8File (Join-Path $Root 'shared-header.html') $header
Write-Utf8File (Join-Path $Root 'shared-footer.html') $footer
Write-Utf8File (Join-Path $BlogDir 'index.html') $blog
foreach($A in $Articles){Write-Utf8File (Join-Path $ArticlesDir "$($A.s).html") (New-Article $A)}
Copy-Item (Join-Path $ImagesDir 'logo-arabsad.jpg') (Join-Path $Root 'favicon.ico') -Force
Copy-Item (Join-Path $ImagesDir 'logo-arabsad.jpg') (Join-Path $Root 'apple-touch-icon.png') -Force
$homePath=Join-Path $Root 'index.html';if(Test-Path $homePath){$h=Get-Content $homePath -Raw -Encoding utf8;if($h -notmatch 'site-banner-arabsad\.jpg'){$h=$h -replace '(<div data-include="shared-footer\.html"></div>)','<div style="max-width:1200px;margin:25px auto;padding:0 16px"><img src="/assets/images/site-banner-arabsad.jpg" alt="إعلانات العرب - إعلانات احترافية على كل المنصات" loading="lazy" style="width:100%;height:auto;border-radius:16px"></div>$1';Write-Utf8File $homePath $h}}
$today=Get-Date -Format 'yyyy-MM-dd';$urls=@("$Site/","$Site/blog/","$Site/services/");foreach($A in $Articles){$urls+="$Site/blog/articles/$($A.s).html"};$xml=@('<?xml version="1.0" encoding="UTF-8"?>','<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">');foreach($u in $urls){$xml+="  <url><loc>$u</loc><lastmod>$today</lastmod><changefreq>monthly</changefreq><priority>0.8</priority></url>"};$xml+='</urlset>';Write-Utf8File (Join-Path $Root 'sitemap.xml') ($xml -join "`n");Write-Utf8File (Join-Path $Root 'robots.txt') "User-agent: *`nAllow: /`n`nSitemap: $Site/sitemap.xml`n"
